import assert from "node:assert/strict";
import test from "node:test";
import { QUESTS } from "../src/data.ts";
import { NECRO_GLYPHS, NECRO_RITUALS, NECRO_UPGRADES } from "../src/necromancyImported.ts";
import { isSkillName } from "../src/skillNames.ts";

// Generated by scripts/import-necromancy.mjs from the Wiki on 2026-11-16: Module:Necromancy/rituals/data,
// Template:Death Skull upgrades, Template:Deathdealer upgrades and the table on Deathwarden robe armour.
const line = (name) => NECRO_UPGRADES.filter((s) => s.line === name);
const quests = new Set(QUESTS.map((q) => q.id));

test("weapon steps run from tier 10 to 90 in tens, ascending", () => {
  assert.deepEqual(line("weapon").map((s) => s.tier), [10, 20, 30, 40, 50, 60, 70, 80, 90]);
  assert.deepEqual(line("deathwarden").map((s) => s.tier), [10, 20, 30, 40, 50, 60, 70, 80, 90]);
});

test("deathdealer starts at tier 70", () => {
  assert.deepEqual(line("deathdealer").map((s) => s.tier), [70, 80, 90]);
  for (const step of line("deathdealer")) assert.ok(step.materials.some((m) => m.item === "Hermodic plate"), `T${step.tier} needs plates`);
  assert.equal(line("deathwarden").find((s) => s.tier === 70).materials.some((m) => m.item === "Hermodic plate"), false);
});

test("tier 70 weapon upgrade is 4 ensouled bars and 50 bone runes per weapon, after The Spirit of War", () => {
  const t70 = line("weapon").find((s) => s.tier === 70);
  assert.deepEqual(t70.materials.map(({ item, qty, per }) => ({ item, qty, per })), [
    { item: "Ensouled bar", qty: 4, per: "weapon" },
    { item: "Bone rune", qty: 50, per: "weapon" },
  ]);
  assert.ok(t70.quests.includes("the-spirit-of-war"));
  assert.equal(t70.task, "Kili's Knowledge V");
  assert.deepEqual(t70.wear, [{ skill: "Necromancy", level: 70 }]);
});

test("every tier from 70 up needs The Spirit of War, and none below it does", () => {
  for (const step of NECRO_UPGRADES) assert.equal(step.quests.includes("the-spirit-of-war"), step.tier >= 70, `${step.line} T${step.tier}`);
});

test("Kili's task per tier: Kili Row at 20, then Kili's Knowledge I to VII, power versions for deathdealer", () => {
  assert.equal(line("weapon").find((s) => s.tier === 10).task, undefined);
  assert.equal(line("weapon").find((s) => s.tier === 20).task, "Kili Row");
  assert.deepEqual(line("weapon").slice(2).map((s) => s.task), ["I", "II", "III", "IV", "V", "VI", "VII"].map((n) => `Kili's Knowledge ${n}`));
  assert.deepEqual(line("deathdealer").map((s) => s.task), ["V", "VI", "VII"].map((n) => `Kili's Knowledge ${n} (power)`));
});

test("wear level equals the tier: Necromancy for weapons, Defence for deathwarden, both for deathdealer", () => {
  // Infoboxes of Deathwarden hood/robe top (tier 70) and Deathdealer hood (tier 70), checked 2026-11-16.
  const skills = { weapon: ["Necromancy"], deathwarden: ["Defence"], deathdealer: ["Defence", "Necromancy"] };
  for (const step of NECRO_UPGRADES) {
    for (const w of step.wear) assert.ok(isSkillName(w.skill));
    assert.deepEqual(step.wear.map((w) => w.skill), skills[step.line], `${step.line} T${step.tier}`);
    for (const w of step.wear) assert.equal(w.level, step.tier === 10 ? 1 : step.tier);
  }
});

test("only tier 10 is free, and it costs nothing to upgrade to", () => {
  for (const step of NECRO_UPGRADES) assert.equal(step.members, step.tier !== 10, `${step.line} T${step.tier}`);
  for (const step of NECRO_UPGRADES.filter((s) => s.tier === 10)) assert.deepEqual(step.materials, []);
  for (const step of NECRO_UPGRADES.filter((s) => s.tier > 10)) assert.ok(step.materials.length > 0, `${step.line} T${step.tier}`);
});

test("steps only name quests that exist, and robes cost per set", () => {
  for (const step of NECRO_UPGRADES) {
    for (const id of step.quests) assert.ok(quests.has(id), `${id} is a quest`);
    for (const m of step.materials) assert.equal(m.per, step.line === "weapon" ? "weapon" : "set");
  }
});

test("every ritual has XP, ticks, inputs and outputs", () => {
  assert.ok(NECRO_RITUALS.length > 0);
  for (const r of NECRO_RITUALS) {
    assert.ok(r.xp > 0 && r.ticks > 0, r.id);
    assert.ok(r.inputs.length > 0 && r.outputs.length > 0, r.id);
    assert.ok([1, 2, 3].includes(r.tier), r.id);
  }
  assert.equal(new Set(NECRO_RITUALS.map((r) => r.id)).size, NECRO_RITUALS.length);
});

test("no ritual at level 20 or below is members-only unless the Wiki flags it, and none above is free", () => {
  // The Wiki's module has no members flag on any ritual (checked 2026-11-16), so the cap alone decides.
  for (const r of NECRO_RITUALS) assert.equal(r.members, r.level > 20, r.id);
});

test("known rituals match the Wiki", () => {
  const lesser = NECRO_RITUALS.find((r) => r.name === "Lesser communion");
  assert.deepEqual([lesser.level, lesser.tier, lesser.xp], [5, 1, 200]);
  const greater = NECRO_RITUALS.find((r) => r.name === "Greater necroplasm");
  assert.deepEqual(greater.inputs.map(({ item, qty }) => ({ item, qty })), [{ item: "Lesser necroplasm", qty: 200 }]);
  assert.equal(greater.outputs.find((o) => o.item === "Greater necroplasm").qty, 100);
  assert.equal(greater.xp, 1480);
  assert.equal(NECRO_RITUALS.find((r) => r.name === "Manifest ectoplasm").level, 95);
});

test("glyphs have a level, tier and ink, and unique ids", () => {
  assert.ok(NECRO_GLYPHS.length > 0);
  for (const g of NECRO_GLYPHS) assert.ok(g.level > 0 && [1, 2, 3].includes(g.tier) && g.ink.endsWith("ghostly ink"), g.id);
  assert.equal(new Set(NECRO_GLYPHS.map((g) => g.id)).size, NECRO_GLYPHS.length);
  assert.equal(NECRO_GLYPHS.find((g) => g.name === "Multiply I").alteration, true);
  assert.equal(NECRO_GLYPHS.find((g) => g.name === "Elemental I").alteration, false);
});
